    { "name": "cancelling-fail", "note": "a cancelling job whose try failed or was lost becomes cancelled" },
    { "name": "lost-is-fail", "note": "lost behaves exactly as fail" }
  ],
  "noOpRule": "a refused command leaves the state unchanged (post == pre)"
}

// Drives the real host and the polygraph spec in lockstep over every action
// sequence up to a depth, checking observable state and accept/refuse agree.
import { test } from 'node:test';
import assert from 'node:assert/strict';
// @ts-ignore -- plain JS helper from the polygraph tool
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import createHost from '../src/host.impl.ts';

const spec = loadSpec(new URL('../spec/jobs.spec.cjs', import.meta.url).pathname.replace(/^\/(\w:)/, '$1'));

const STEPS: [string, any][] = [
  ...[0, 1, 2, 3, 4].map((m) => ['SUBMIT', { maxTries: m }] as [string, any]),
  ['CLAIM', {}], ['SUCCEED', {}], ['FAIL', {}], ['LOST', {}], ['CANCEL', {}],
];

async function run(seq: [string, any][]) {
  const h = await createHost();
  spec.init();
  for (const [a, d] of seq) {
    const before = JSON.stringify(spec.getState());
    const r = a === 'SUBMIT' ? await h.submit('j', d.maxTries) : await (h as any)[a.toLowerCase()]('j');
    spec.actions[a](d);
    const s = spec.getState();
    const v = await h.job('j');
    const view = v ?? { status: 'none', tries: 0, maxTries: 0 };
    assert.deepEqual({ ...view }, { status: s.status, tries: s.tries, maxTries: s.maxTries }, JSON.stringify(seq));
    assert.equal(r.ok, JSON.stringify(s) !== before, `accept/refuse mismatch ${JSON.stringify(seq)}`);
  }
}

test('host conforms to spec on all sequences up to depth 6', async () => {
  // past depth 3, only extend sequences that begin with a valid submit
  let frontier: [string, any][][] = [[]];
  for (let depth = 1; depth <= 6; depth++) {
    const nextF: [string, any][][] = [];
    for (const p of frontier) for (const st of STEPS) {
      if (depth > 1 && p[0][0] === 'SUBMIT' && depth > 3 && st[0] === 'SUBMIT') continue;
      const seq = [...p, st];
      await run(seq);
      nextF.push(seq);
    }
    frontier = depth < 3 ? nextF : nextF.filter((s) => s[0][0] === 'SUBMIT' && s[0][1].maxTries >= 1 && s[0][1].maxTries <= 3);
  }
});

