// SAM v2 strict spec of src/jobs.ts: the lifecycle of ONE job id.
// Jobs are independent, so one id covers the per-job rules; status 'none'
// stands for "never submitted" (host returns null / refuses every command).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'none', tries: 0, maxTries: 0 };

const intent = (domain = [{}], schema = {}) => ({ action: (data = {}) => ({ ...data }), schema, domain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      tries: { type: 'number' },
      maxTries: { type: 'number' },
    },
    actions: {
      SUBMIT: intent([{ maxTries: 0 }, { maxTries: 1 }, { maxTries: 2 }, { maxTries: 3 }, { maxTries: 4 }], { maxTries: 'number' }),
      CLAIM: intent(),
      SUCCEED: intent(),
      FAIL: intent(),
      LOST: intent(),
      CANCEL: intent(),
      HOLD: intent(),
      RELEASE: intent(),
    },
    acceptors: {
      SUBMIT: (model) => (proposal, { reject, next }) => {
        const m = proposal.maxTries;
        if (!Number.isInteger(m) || m < 1 || m > 3) return reject('maxTries must be 1 to 3');
        if (model.status !== 'none') return reject('job already exists');
        next.status = 'queued';
        next.tries = 0;
        next.maxTries = m;
      },
      CLAIM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'queued') return reject('not queued');
        if (model.tries >= model.maxTries) return reject('no tries left');
        next.status = 'running';
        next.tries = model.tries + 1;
        unchanged('maxTries');
      },
      SUCCEED: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'running' && model.status !== 'cancelling') return reject('not running');
        next.status = 'succeeded';
        unchanged('tries', 'maxTries');
      },
      FAIL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'cancelling') {
          next.status = 'cancelled';
        } else if (model.status === 'running') {
          next.status = model.tries < model.maxTries ? 'queued' : 'failed';
        } else {
          return reject('not running');
        }
        unchanged('tries', 'maxTries');
      },
      LOST: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'cancelling') {
          next.status = 'cancelled';
        } else if (model.status === 'running') {
          next.status = model.tries < model.maxTries ? 'queued' : 'failed';
        } else {
          return reject('not running');
        }
        unchanged('tries', 'maxTries');
      },
      HOLD: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'queued') return reject('not queued');
        next.status = 'held';
        unchanged('tries', 'maxTries');
      },
      RELEASE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'held') return reject('not held');
        next.status = 'queued';
        unchanged('tries', 'maxTries');
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'queued' || model.status === 'held') next.status = 'cancelled';
        else if (model.status === 'running') next.status = 'cancelling';
        else return reject('cannot cancel');
        unchanged('tries', 'maxTries');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  SUBMIT: (data = {}) => intents.SUBMIT(data),
  CLAIM: (data = {}) => intents.CLAIM(data),
  SUCCEED: (data = {}) => intents.SUCCEED(data),
