import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('submit validation', async () => {
  const h = await createHost();
  assert.equal((await h.submit('a', 0)).ok, false);
  assert.equal((await h.submit('a', 4)).ok, false);
  assert.equal((await h.submit('a', 1.5)).ok, false);
  assert.equal(await h.job('a'), null);
  assert.deepEqual(await h.submit('a', 2), { ok: true });
  assert.equal((await h.submit('a', 2)).ok, false);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
});

test('unknown job refused', async () => {
  const h = await createHost();
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel', 'hold', 'release'] as const) {
    assert.equal((await h[c]('x')).ok, false);
  }
});

test('retries then fail', async () => {
  const h = await createHost();
  await h.submit('a', 2);
  assert.ok((await h.claim('a')).ok);
  assert.ok((await h.fail('a')).ok);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  assert.ok((await h.claim('a')).ok);
  assert.ok((await h.lost('a')).ok);
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  assert.equal((await h.claim('a')).ok, false);
  assert.equal((await h.fail('a')).ok, false);
});

test('hold and release', async () => {
  const h = await createHost();
  await h.submit('a', 2);
  assert.equal((await h.release('a')).ok, false);
  assert.ok((await h.hold('a')).ok);
  assert.deepEqual(await h.job('a'), { status: 'held', tries: 0, maxTries: 2 });
  assert.equal((await h.hold('a')).ok, false);
  assert.equal((await h.claim('a')).ok, false);
  assert.equal((await h.succeed('a')).ok, false);
  assert.equal((await h.fail('a')).ok, false);
  assert.ok((await h.release('a')).ok);
